// Category B: no behaviour at all. It owns the one look a picture needs inside a page, its corner and
// the clip that draws it, so a Block can place a photo, video or artwork without setting a radius it
// is not allowed to own (block-contract.md § 3). The ratio stays AspectRatio's: compose it inside.
import type { CSSProperties, HTMLAttributes, Ref } from "react";
import "./Media.css";

type MediaVariant = "plain" | "well";
type MediaFit = "cover" | "contain";

export interface MediaProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * `plain` (default) paints nothing behind the picture, which brings its own background.
   * `well` sets the picture on a neutral plate, for a cut-out with a transparent background (a
   * device render), which would otherwise float on the card's surface.
   *
   * @default "plain"
   */
  variant?: MediaVariant;
  /**
   * How a picture that is Media's direct child, or the direct child of an `AspectRatio` inside it,
   * fills the box: Media sizes it to 100% and sets this `object-fit`. `cover` crops a photograph
   * to the box; `contain` fits a cut-out whole on the plate. Only `img`, `svg` and `video` are
   * fitted; any other node sizes itself.
   *
   * @default `"cover"` when `variant="plain"`, `"contain"` when `variant="well"`
   */
  fit?: MediaFit;
  /**
   * Sits flush in a band that draws its own corners (Card's `CardMedia`): no radius of its own, so
   * the picture meets the band's edges square and the band's curve is the only one.
   *
   * @default false
   */
  isFlush?: boolean;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

/**
 * A rounded frame around a picture, video or artwork. It clips, so a link or button belongs AROUND it,
 * never inside: the clip would cut that control's focus ring.
 */
export function Media({ variant = "plain", fit, isFlush = false, className, ...props }: MediaProps) {
  return (
    <div
      {...props}
      data-variant={variant}
      data-fit={fit ?? (variant === "well" ? "contain" : "cover")}
      data-flush={isFlush || undefined}
      className={className ? `sd-media ${className}` : "sd-media"}
    />
  );
}

/* Media.css — .sd-media
   A corner and the clip that draws it, around a picture. A plain block box, so whatever the slot holds
   keeps its normal flow. Media also fills and fits the picture itself (prop-usage-contract.md § Fill),
   so no consumer hand-writes `object-fit`: the one it forgets renders at its intrinsic size. */
.sd-media {
  /* State on root, style on child (component-contract.md § 6.5): `data-fit` picks the object-fit
     the picture below reads. */
  --sd-media-fit-current: cover;
  overflow: hidden;
  border-radius: var(--sd-media-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}

/* isFlush: the band around the picture owns the corner, so Media draws none. */
.sd-media[data-flush] {
  border-radius: 0;
}

/* well: a neutral plate behind a cut-out that brings no background of its own. */
.sd-media[data-variant="well"] {
  background: var(--sd-media-background-well);
}

.sd-media[data-fit="contain"] {
  --sd-media-fit-current: contain;
}

/* The picture: a direct child, or the direct child of the AspectRatio that owns the ratio inside
   Media. Child combinators only, two fixed steps (§ 6.2 forbids descendant ones); any other node
   (a placeholder div, a thumbnail) sizes itself. Inside an auto-height Media the 100% block size
   resolves to auto, so a picture at its own ratio keeps it. */
.sd-media > img,
.sd-media > svg,
.sd-media > video,
.sd-media > .sd-aspect-ratio > img,
.sd-media > .sd-aspect-ratio > svg,
.sd-media > .sd-aspect-ratio > video {
  display: block;
  inline-size: 100%;
  block-size: 100%;
  object-fit: var(--sd-media-fit-current);
}
